import { expect, test } from "bun:test";
import {
	clampPiEffort,
	piEffortsFor,
	piEffortsWithin,
	piEffortLevels,
	type PiProvider,
} from "../apps/client/src/lib/projects/pi-models.ts";

/* `/api/pi/models`가 그대로 내려주는 모양: provider 하나에 모델 목록, 모델마다 허용 level. */
const providers: PiProvider[] = [
	{
		id: "opencode-go",
		label: "OpenCode Go",
		models: [
			{
				id: "opencode-go/deepseek-v4.1-flash",
				name: "DeepSeek V4.1 Flash",
				provider: "opencode-go",
				efforts: ["low", "high", "max"],
			},
			{
				id: "opencode-go/grok-4.7",
				name: "Grok 4.7",
				provider: "opencode-go",
				efforts: ["low", "medium", "high", "xhigh"],
			},
		],
	},
	{
		id: "xai",
		label: "xAI",
		models: [{ id: "xai/grok-4.6", name: "Grok 4.6", provider: "xai", efforts: ["low", "medium", "high", "xhigh"] }],
	},
];

test("piEffortsFor returns the catalog's levels for a model that is still there", () => {
	expect(piEffortsFor(providers, "opencode-go/deepseek-v4.1-flash")).toEqual(["low", "high", "max"]);
});

test("piEffortsFor finds the same model under another provider when the id moved", () => {
	/* 등급 파일의 premium 줄이 `opencode-go/grok-4.6`이었고 카탈로그에는 `xai/grok-4.6`만 남았다. */
	expect(piEffortsFor(providers, "opencode-go/grok-4.6")).toEqual(["low", "medium", "high", "xhigh"]);
});

test("piEffortsFor never returns an empty list: a gone model keeps every level", () => {
	expect(piEffortsFor(providers, "opencode-go/retired-model")).toEqual([...piEffortLevels]);
	expect(piEffortsFor([], "opencode-go/deepseek-v4.1-flash")).toEqual([...piEffortLevels]);
});

test("piEffortsFor does not answer from a longer id that merely ends with the name", () => {
	expect(
		piEffortsFor(
			[{ id: "x", label: "X", models: [{ id: "x/grok-4.6-pro", name: "p", provider: "x", efforts: ["high"] }] }],
			"y/grok-4.6",
		),
	).toEqual([...piEffortLevels]);
});

/* Claude proxy 사다리: pi tiers와 같은 카탈로그에서, cc-proxy가 보내는 `output_config.effort`(low–max)만. */
const PROXY = ["low", "medium", "high", "xhigh", "max"] as const;

test("piEffortsWithin keeps the model's levels the receiver knows, in Pi order", () => {
	const flash: PiProvider[] = [
		{
			id: "opencode-go",
			label: "OpenCode Go",
			models: [{ id: "opencode-go/f", name: "f", provider: "opencode-go", efforts: ["off", "low", "high", "max"] }],
		},
	];
	expect(piEffortsWithin(flash, "opencode-go/f", PROXY)).toEqual(["low", "high", "max"]);
	expect(piEffortsWithin(providers, "xai/grok-4.6", PROXY)).toEqual(["low", "medium", "high", "xhigh"]);
});

test("piEffortsWithin opens the receiver's whole list when the model is gone or nothing overlaps", () => {
	expect(piEffortsWithin(providers, "xai/retired", PROXY)).toEqual([...PROXY]);
	const offOnly: PiProvider[] = [
		{ id: "p", label: "P", models: [{ id: "p/m", name: "m", provider: "p", efforts: ["off"] }] },
	];
	expect(piEffortsWithin(offOnly, "p/m", PROXY)).toEqual([...PROXY]);
});

test("a fixed proxy effort moves to the nearest level the new model takes", () => {
	/* grok(medium 있음) → flash(medium 없음): Pi `clampThinkingLevel`처럼 위쪽 high. */
	const flashEfforts = piEffortsWithin(providers, "opencode-go/deepseek-v4.1-flash", PROXY);
	expect(clampPiEffort(flashEfforts, "medium")).toBe("high");
	expect(clampPiEffort(piEffortsWithin(providers, "xai/grok-4.6", PROXY), "max")).toBe("xhigh");
});

