export function savePiFilter(next: {
	enabled: boolean;
	providers: Record<string, string[]>;
	version: string;
}): Promise<PiFilterView> {
	return request<PiFilterView>("/api/pi/model-filter", {
		method: "PUT",
		body: JSON.stringify(next),
	});
}

/** 대시보드만의 free 포함 여부(`~/.local/state/dashboard/model-filter.json`). */
export function saveFreeModels(includeFree: boolean): Promise<PiFilterView> {
	return request<PiFilterView>("/api/pi/model-filter/free", {
		method: "PUT",
		body: JSON.stringify({ includeFree }),
	});
}

