 * (빈 이름이 버튼에 남지 않게).
 */
export function resolvePiModel(
	providers: PiProvider[],
	current: string,
	fallback: string,
	hidden: string[] = [],
): string {
	const all = providers.flatMap((provider) => provider.models.map((model) => model.id));
	if (all.length === 0) return current;
	if (all.includes(current) || hidden.includes(current)) return current;
	if (all.includes(fallback)) return fallback;
	return all[0] ?? current;
}

